func remove(head *Node, value int) *Node {
    if head != nil && head.Value == value {
        return head.Next
    }
    for n := head; n != nil && n.Next != nil; n = n.Next {
        if n.Next.Value == value {
            n.Next = n.Next.Next
            break
        }
    }
    return head
}

