type Stack struct {
    top *Node
}

func (s *Stack) Push(value int) {
    s.top = &Node{Value: value, Next: s.top}
}

func (s *Stack) Pop() (int, bool) {
    if s.top == nil {
        return 0, false
    }
    value := s.top.Value
    s.top = s.top.Next
    return value, true
}

